    parameter A=0, B=1, C=2, D=3, E=4, F=5;
    always @(*) begin
        case (state)
            A: next = w ? A : B;
            B: next = w ? D : C;
            C: next = w ? D : E;
            D: next = w ? A : F;
            E: next = w ? D : E;
            F: next = w ? D : C;
        endcase
    end
    always @(posedge clk) begin
        if (reset) state <= A;
        else state <= next;
    end
    assign z = (state == E) || (state == F);
endmodule
